import {ToolRegistry} from './registry.js';

function registerWeatherTool(registry: ToolRegistry, executorCalls: {value: number}): void {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async () => {
      executorCalls.value += 1;
      return 'sunny';
    }
  );
}

